  super.afterCandidate(candidate,facts);var service=new JdbcMinutesSettingsCommands(ama.api.Task09RuntimeProbe.components(app).authority(),this::snapshot,pin,prompt,model,new TranscriptAcquisitionBudget(16777216,16777216,16777216,268435456,134217728,8388608,128,256,256));String old=j.queryForObject("SELECT exclusion_revision_id FROM meeting WHERE id=?",String.class,meeting);var saved=j.queryForMap("SELECT minutes_revision_id,element_set_id,transcript_confirmation_id,generation_fingerprint FROM meeting WHERE id=?",meeting);var pairs=j.queryForList("SELECT d.category,s.locator_id FROM sensitive_detection d JOIN sensitive_detection_source s ON s.detection_id=d.id WHERE d.set_id=(SELECT element_set_id FROM meeting WHERE id=?) ORDER BY d.category,s.locator_id",meeting);assertEquals(2,pairs.size());var items=pairs.stream().map(row->new JdbcMinutesSettingsCommands.Exclusion((String)row.get("locator_id"),(String)row.get("category"),null)).toList();var changed=assertDoesNotThrow(()->service.replaceExclusions(actor(),meeting,"actual-exclusions",14,old,items,UUID.randomUUID().toString()));String fresh=(String)changed.get("resultId");assertNotEquals(old,fresh);assertEquals(2L,j.queryForObject("SELECT revision FROM exclusion_revision WHERE id=?",Long.class,fresh));assertEquals(2,j.queryForObject("SELECT COUNT(*) FROM sensitive_exclusion WHERE revision_id=?",Integer.class,fresh));assertEquals(0,j.queryForObject("SELECT COUNT(*) FROM sensitive_exclusion WHERE revision_id=?",Integer.class,old));assertEquals(1,j.queryForObject("SELECT needs_generation FROM meeting WHERE id=?",Integer.class,meeting));assertEquals(saved,j.queryForMap("SELECT minutes_revision_id,element_set_id,transcript_confirmation_id,generation_fingerprint FROM meeting WHERE id=?",meeting));
  archiveUnavailable.set(true);assertEquals(true,service.replaceExclusions(actor(),meeting,"actual-exclusions",14,old,items,UUID.randomUUID().toString()).get("replayed"));archiveUnavailable.set(false);String selected=j.queryForObject("SELECT template_revision_id FROM meeting WHERE id=?",String.class,meeting);var template=service.selectTemplate(actor(),meeting,"actual-template",15,selected,UUID.randomUUID().toString());assertEquals(selected,template.get("resultId"));assertEquals(16L,j.queryForObject("SELECT revision FROM meeting WHERE id=?",Long.class,meeting));assertEquals(fresh,j.queryForObject("SELECT exclusion_revision_id FROM meeting WHERE id=?",String.class,meeting));assertEquals(saved,j.queryForMap("SELECT minutes_revision_id,element_set_id,transcript_confirmation_id,generation_fingerprint FROM meeting WHERE id=?",meeting));
